
import requests
import streamlit as st

API_URL = "http://127.0.0.1:8000"

st.set_page_config(
    page_title="Flame in Freefall",
    page_icon="🔥",
    layout="wide",
)

st.title("🔥 Flame in Freefall")
st.caption(
    "AI-powered insights from microgravity combustion experiments"
)

st.info(
    "Experimental evidence represents recorded observations. "
    "ML predictions are generated by a model trained on simulated data."
)

with st.sidebar:
    st.header("Research tools")
    st.write("Ask questions about combustion experiments.")
    st.write("Inspect source experiments and model outputs.")
    st.divider()
    st.caption("Research and educational use only.")

question = st.text_area(
    "Ask a research question",
    placeholder=(
        "How does oxygen concentration relate to flame "
        "extinction in the retrieved experiments?"
    ),
    height=100,
)

if st.button("Analyze", type="primary"):
    if not question.strip():
        st.warning("Enter a question first.")
    else:
        try:
            with st.spinner("Retrieving evidence and generating insights..."):
                api_response = requests.post(
                    f"{API_URL}/ask",
                    json={"question": question.strip()},
                    timeout=180,
                )
                api_response.raise_for_status()
                data = api_response.json()

            st.subheader("Research answer")
            st.write(data.get("answer") or "No answer returned.")

            st.divider()
            st.subheader("Experimental evidence")

            evidence = data.get("experimental_evidence") or []

            if evidence:
                for item in evidence:
                    experiment_id = item.get(
                        "experiment_id", "Unknown experiment"
                    )

                    with st.expander(experiment_id, expanded=True):
                        st.write(
                            "**Source:**",
                            item.get("source", "Not specified"),
                        )

                        # These are observed experimental values,
                        # not model predictions.
                        for key, value in item.items():
                            if key not in {
                                "experiment_id", "source", "finding"
                            } and value is not None:
                                st.write(f"**{key}:** {value}")

                        if item.get("finding"):
                            st.write(item["finding"])
            else:
                st.warning("No experimental evidence was returned.")

            st.divider()
            st.subheader("ML fire prediction")
            prediction = data.get("prediction")

            if prediction is None:
                st.info("No matching ML prediction is available.")
            else:
                # The backend may return one prediction or a list.
                predictions = (
                    prediction
                    if isinstance(prediction, list)
                    else [prediction]
                )

                for pred in predictions:
                    if not isinstance(pred, dict):
                        continue

                    with st.container(border=True):
                        st.write(
                            "**Experiment:**",
                            pred.get("experiment_id", "Not specified"),
                        )
                        st.write(
                            "**Predicted label:**",
                            pred.get("label", "Not available"),
                        )

                        probability = pred.get("probability")
                        if isinstance(probability, (int, float)):
                            st.metric(
                                "Model probability",
                                f"{probability:.1%}",
                            )

                        st.write(
                            "**Risk band:**",
                            pred.get("riskBand", "Not available"),
                        )
                        st.write(
                            "**Model:**",
                            pred.get("model", "Not specified"),
                        )

                        if pred.get("note"):
                            st.caption(pred["note"])

            st.warning(data.get(
                "prediction_notice",
                "Model predictions are not certified safety guidance.",
            ))

            st.divider()
            st.subheader("Observed trends")
            for trend in data.get("observed_trends") or []:
                st.markdown(f"- {trend}")

            st.subheader("Interpretation")
            st.write(data.get("interpretation") or "Not available.")

            st.subheader("Safety insight")
            st.write(data.get("safety_insight") or "Not available.")

            st.subheader("Limitations")
            limitations = data.get("limitations") or []

            if limitations:
                for limitation in limitations:
                    st.markdown(f"- {limitation}")
            else:
                st.write("No limitations were returned.")

            st.divider()
            st.subheader("Sources")
            sources = data.get("sources") or []

            if sources:
                for source in sources:
                    st.markdown(f"- `{source}`")
            else:
                st.write("No source identifiers were returned.")

            with st.expander("Technical metadata"):
                st.json({
                    "model_used": data.get("model_used"),
                    "answerability": data.get("answerability"),
                })

        except requests.exceptions.RequestException as exc:
            st.error(f"Could not reach the API: {exc}")
        except (ValueError, TypeError) as exc:
            st.error(f"Unexpected API response: {exc}")
